import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, uv, mul, float } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {string} [depthMapUrl]
 * @property {Array<{name:string,params:any,trigger?:string}>} [cinematicPrimitives]
 * @property {Array<any>} [textContent]
 * @property {Array<any>} [intent]
 * @property {Array<any>} [cinematicPrimitives]
 * @property {Array<any>} [neighbors]
 * @property {Array<any>} [graphics]
 * @property {Array<any>} [animations]
 * @property {Object} [colors]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {any} textureLoader
 * @property {any} glbLoader
 * @property {any} videoLoader
 * @property {any} fontAtlas
 * @property {any} primitives
 * @property {any} emit
 * @property {string} [tier]
 */

/**
 * Creates a parallax card node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  const root = new Group();

  // ----- Geometry & Material -----
  const geometry = new PlaneGeometry(1.5, 0.9, 64, 64);
  const material = new MeshStandardNodeMaterial();
  material.metalness = 0.5;
  material.roughness = 0.6;
  material.clearcoat = 0.2;
  material.clearcoatRoughness = 0.1;

  const mesh = new Mesh(geometry, material);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  root.add(mesh);

  // ----- Load Textures -----
  /** @type {THREE.Texture|null} */
  let baseTex = null;
  /** @type {THREE.Texture|null} */
  let depthTex = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      baseTex = tex;
      material.colorNode = texture(tex, uv());
      material.needsUpdate = true;
    });
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthTex = tex;
      // Displace up to ~0.08 units (tuned for subtle depth)
      material.displacementNode = mul(texture(tex, uv()), float(0.08));
      material.needsUpdate = true;
    });
  }

  // ----- Position / Rotation / Scale from Config -----
  if (Array.isArray(config.position)) {
    root.position.set(...config.position);
  }
  if (Array.isArray(config.rotation)) {
    root.rotation.set(...config.rotation);
  }
  if (Array.isArray(config.scale)) {
    root.scale.set(...config.scale);
  }

  // ----- Cinematic Primitives -----
  const primitiveCleanups = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[prim.name];
      if (fn) {
        const instance = fn(root, prim.params || {});
        if (instance?.cleanup) primitiveCleanups.push(instance.cleanup);
        // timelines are owned by the primitive; they will be killed in cleanup
      }
    }
  }

  // ----- Interaction Handlers -----
  const originalY = mesh.position.y;
  let hoverTimeline = null;
  let pressTimeline = null;

  const handlers = {};

  // Hover lift (rise‑in)
  handlers.hover = {
    enter: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.timeline();
      hoverTimeline.to(
        mesh.position,
        { y: originalY + 0.15, duration: 0.7, ease: 'power3.out' }
      );
    },
    leave: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.timeline();
      hoverTimeline.to(
        mesh.position,
        { y: originalY, duration: 0.5, ease: 'power2.inOut' }
      );
    },
  };

  // Click: press‑down + emit event
  handlers.click = () => {
    if (pressTimeline) pressTimeline.kill();
    pressTimeline = gsap.timeline();
    pressTimeline
      .to(
        mesh.scale,
        { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' }
      )
      .add(() => {
        ctx.emit('hub-features.select', {});
      });
  };

  root.userData.handlers = handlers;

  // ----- Cleanup -----
  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (baseTex && baseTex.dispose) baseTex.dispose();
    if (depthTex && depthTex.dispose) depthTex.dispose();
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTimeline) pressTimeline.kill();
    for (const clean of primitiveCleanups) {
      try {
        clean();
      } catch (e) {
        // ignore errors during cleanup
      }
    }
  };

  return root;
}
